from __future__ import annotations

from pathlib import Path
import ast
import base64
import gzip
import hashlib
import py_compile
import shutil
import sys

ROOT = Path.cwd()
BACKEND = ROOT / "wa_backend"
BACKUP = ROOT / ".patch_backups" / "DISPATCH_POLICY_OPERATIONAL_HARDENING"
TARGETS = ['models.py', 'schemas.py', 'services.py', 'api/driver.py', 'api/dispatch.py']
EXPECTED = {'models.py': 'c6d247b0264663a8905052cef08669f94ae4b3ec0532692861bea52cca69e5d4', 'schemas.py': '4dae185d263d6c8b55992254933048c09ebc4f951ed872be8e942f73e696e0b4', 'services.py': 'aaa32a4923425f754925b7df6d47bc6c7cb1022cb060572295e43b326ceca228', 'api/driver.py': '703fbeaf92130bbe2d845b83de25464bcd9bcf73a7564b504505dffc630cf7b1', 'api/dispatch.py': '965209adc94ac7eb0352d1308a7a2c45a936ccc5e942e4c955324f5bceebcca4'}
PATCHED = {'models.py': '51aed08e44b571b49156c0a0e966e4b8e990e69b3272774f35b437cd2859b0b6', 'schemas.py': '413c5e21493edd613ddf85fb0b629a55887f7bfcaf82f6a8e198e3b61ad6d660', 'services.py': '8f7d06f017ed19595c1d9d8dcdbe0e7726cb50f73d18c00e06714f4c8f64b632', 'api/driver.py': 'e5620fbc3f9e845dd0e5466dfc034f7bccdff04363b77ba9979e49d711a37d53', 'api/dispatch.py': '51f0528612fff8ca80a8effcdf90e570d4977961cba9e9fbe8360197adf5d40c'}
PAYLOADS = {'models.py': '', 'schemas.py': '', 'services.py': '', 'api/driver.py': '', 'api/dispatch.py': ''}


def normalize(data: bytes) -> bytes:
    return data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")


def digest(data: bytes) -> str:
    return hashlib.sha256(normalize(data)).hexdigest()


def decode_payload(value: str) -> bytes:
    return gzip.decompress(base64.b64decode(value.encode("ascii")))


def validate_source(rel: str, data: bytes) -> None:
    compile(normalize(data).decode("utf-8"), rel, "exec")
    ast.parse(normalize(data).decode("utf-8"), filename=rel)


def main() -> None:
    if not BACKEND.is_dir():
        raise SystemExit("ERROR: شغّل الباتش من جذر مشروع wanasah.")

    originals = {}
    styles = {}
    current = {}
    for rel in TARGETS:
        path = BACKEND / rel
        if not path.is_file():
            raise SystemExit(f"ERROR: الملف غير موجود: {rel}")
        raw = path.read_bytes()
        originals[rel] = raw
        styles[rel] = "CRLF" if b"\r\n" in raw else "LF"
        current[rel] = digest(raw)

    if all(current[rel] == PATCHED[rel] for rel in TARGETS):
        print("DISPATCH_POLICY_OPERATIONAL_HARDENING_ALREADY_OK")
        return

    bad = [rel for rel in TARGETS if current[rel] != EXPECTED[rel]]
    if bad:
        details = "\n".join(
            f"  {rel}: expected={EXPECTED[rel]} current={current[rel]}"
            for rel in bad
        )
        raise SystemExit(
            "ERROR: الملفات الحالية لا تطابق النسخة التي بُني عليها الباتش. لم يتم تعديل أي ملف.\n"
            + details
        )

    prepared = {}
    for rel in TARGETS:
        data = decode_payload(PAYLOADS[rel])
        if digest(data) != PATCHED[rel]:
            raise SystemExit(f"ERROR: payload hash mismatch: {rel}")
        validate_source(rel, data)
        prepared[rel] = data

    BACKUP.mkdir(parents=True, exist_ok=True)
    for rel, raw in originals.items():
        backup_path = BACKUP / rel
        backup_path.parent.mkdir(parents=True, exist_ok=True)
        backup_path.write_bytes(raw)

    try:
        for rel, data in prepared.items():
            out = data if styles[rel] == "LF" else data.replace(b"\n", b"\r\n")
            (BACKEND / rel).write_bytes(out)

        for rel in TARGETS:
            py_compile.compile(str(BACKEND / rel), doraise=True)
            written = (BACKEND / rel).read_bytes()
            if digest(written) != PATCHED[rel]:
                raise RuntimeError(f"post-write hash mismatch: {rel}")

        # Hostile static invariants on the two field routers.
        driver_src = normalize((BACKEND / "api/driver.py").read_bytes()).decode("utf-8")
        dispatch_src = normalize((BACKEND / "api/dispatch.py").read_bytes()).decode("utf-8")
        models_src = normalize((BACKEND / "models.py").read_bytes()).decode("utf-8")
        services_src = normalize((BACKEND / "services.py").read_bytes()).decode("utf-8")
        schemas_src = normalize((BACKEND / "schemas.py").read_bytes()).decode("utf-8")

        forbidden_legacy = (
            "MainWarehouse", "VehicleLoad", "WarehouseLedger", "InventoryLedger",
            "InventoryTransfer(",
        )
        for token in forbidden_legacy:
            if token in driver_src or token in dispatch_src:
                raise RuntimeError(f"legacy inventory symbol remains: {token}")
        if "InventoryBalance(" in driver_src or "InventoryBalance(" in dispatch_src:
            raise RuntimeError("endpoint direct InventoryBalance construction/write detected")

        required = (
            "financial_unit_price_snapshot",
            "operational_date = Column(Date, nullable=False",
            "interval_days = Column(Integer",
            "archived_due_to_zone_id = Column(Integer",
            "async def force_cancel_handshake(",
            "ShortageRequest.driver_id == driver_id",
            "class RestoreZoneRequest(RequestModel)",
            "class ForceCancelHandshakeRequest(RequestModel)",
        )
        combined = "\n".join((models_src, services_src, schemas_src, driver_src, dispatch_src))
        missing = [token for token in required if token not in combined]
        if missing:
            raise RuntimeError("required policy marker missing: " + ", ".join(missing))

        if "schedule_frequency = Column" in models_src or "visit_day          = Column" in models_src or "custom_days        = Column" in models_src:
            raise RuntimeError("legacy textual Zone scheduling columns remain in models.py")
        if "datetime.combine" in driver_src or "datetime.combine" in dispatch_src:
            raise RuntimeError("UTC-naive visit-day boundary logic remains")

        for rel, src in (("driver.py", driver_src), ("dispatch.py", dispatch_src)):
            tree = ast.parse(src)
            missing_dates = []
            for node in ast.walk(tree):
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "Visit":
                    fields = {kw.arg for kw in node.keywords if kw.arg}
                    if "operational_date" not in fields:
                        missing_dates.append(node.lineno)
            if missing_dates:
                raise RuntimeError(f"Visit constructors without operational_date in {rel}: {missing_dates}")

        # ORM relationship/DDL verification: catches ambiguous FK regressions before DB rebuild.
        sys.path.insert(0, str(BACKEND))
        import models as _models
        from sqlalchemy.orm import configure_mappers
        from sqlalchemy.schema import CreateTable
        from sqlalchemy.dialects import postgresql
        configure_mappers()
        for table_name in ("zones", "shops", "visits", "inventory_movements"):
            str(CreateTable(_models.Base.metadata.tables[table_name]).compile(dialect=postgresql.dialect()))

    except Exception:
        for rel, raw in originals.items():
            (BACKEND / rel).write_bytes(raw)
        raise

    print("DISPATCH_POLICY_OPERATIONAL_HARDENING_OK")
    print("SHORTAGE_PRICE_OK: DRIVER_SHORTAGE carries immutable financial_unit_price_snapshot")
    print("EMERGENCY_OWNER_OK: Pending emergency Visit belongs to its driver; no implicit cross-driver adoption")
    print("EMERGENCY_FULFILLMENT_OK: sale fulfills only unassigned/own shortages")
    print("OPERATIONAL_DAY_OK: Visit.operational_date uses company-local day; UTC timestamps remain audit truth")
    print("SCHEDULE_OK: Zone recurrence is numeric start_date + interval_days only")
    print("SHOP_MOVE_OK: active-route Pending visit blocks cross-zone shop move")
    print("ZONE_RESTORE_OK: zone-only / selected / auto-archived restore uses provenance")
    print("HANDSHAKE_FORCE_CANCEL_OK: admin cancellation releases reservation only; no PHYSICAL stock move")
    print("TENANT_ENGINE_OK: unified inventory engine retained; legacy/direct balance writes absent")
    print("MAPPERS_DDL_OK: SQLAlchemy relationships + PostgreSQL DDL compile for changed tables")
    print("FILES_CHANGED: models.py + schemas.py + services.py + api/driver.py + api/dispatch.py")
    print("NEXT: rebuild empty development schema once, then run PostgreSQL policy E2E")


if __name__ == "__main__":
    main()
